from .branding import COMMON_CSS, LOGO_DATA_URI

AI_HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agent White AI Analyst</title><style>
__AW_COMMON_CSS__
.ai-grid{display:grid;grid-template-columns:minmax(0,.72fr) minmax(0,1.28fr);gap:10px}.selector-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.selector-grid select{width:100%;margin-top:5px;background:#010605;color:white;border:1px solid rgba(0,245,154,.18);border-radius:7px;padding:9px}.priority{padding:10px;border-left:3px solid var(--aw-green);background:rgba(1,9,7,.65);margin:7px 0;border-radius:7px}.priority b{color:var(--aw-green)}.analysis-box{min-height:360px}.engine-card{display:grid;grid-template-columns:100px 1fr;gap:10px;align-items:center}.brain{width:90px;height:90px;border-radius:50%;display:grid;place-items:center;border:1px solid rgba(37,223,255,.35);box-shadow:0 0 30px rgba(37,223,255,.09),inset 0 0 30px rgba(0,245,154,.06);font-size:38px;color:var(--aw-cyan)}@media(max-width:900px){.ai-grid{grid-template-columns:1fr}.selector-grid{grid-template-columns:1fr}}
</style></head><body><div class="aw-app"><aside class="aw-sidebar"><div class="aw-brand"><img class="aw-logo" src="__AW_LOGO__" alt="Agent White logo"><div><div class="aw-wordmark">AGENT <span>WHITE</span></div><div class="aw-tagline">LOCAL AI ANALYST</div></div></div><nav class="aw-nav"><a href="/"><span class="ico">▦</span>Dashboard</a><a href="/workspace"><span class="ico">◎</span>Targets</a><a href="/workspace"><span class="ico">⌘</span>Network</a><a class="active" href="/ai"><span class="ico">◉</span>Intelligence</a><a href="/workspace"><span class="ico">⊕</span>Threat Hunting</a><a href="/tools"><span class="ico">⌁</span>Tools</a><a href="/api/export" target="_blank"><span class="ico">▤</span>Reports</a></nav><div class="aw-sidebar-foot"><span class="aw-green">● EVIDENCE-GROUNDED</span><br>Analyzes recorded AgentWhite findings only</div></aside><main class="aw-main"><div class="aw-topbar"><div><div class="aw-wordmark" style="font-size:16px">AI <span>ANALYST</span></div><div class="aw-muted">Local evidence analysis with deterministic fallback when Ollama is unavailable.</div></div><div class="aw-topstatus"><span class="aw-pill ok">Local Evidence</span><a class="aw-btn blue" href="/workspace">Target Workspaces</a></div></div><div class="ai-grid"><div><section class="aw-panel"><div class="aw-panel-head"><h2>◉ ANALYSIS CONTROLS</h2></div><div class="aw-panel-body"><div class="selector-grid"><label class="aw-muted">Target<select id="device"><option value="">All recorded findings</option></select></label><label class="aw-muted">Model<select id="model"><option value="">Automatic / offline fallback</option></select></label></div><button class="aw-btn primary" style="width:100%;margin-top:9px" onclick="analyze()">Analyze Evidence</button></div></section><section class="aw-panel" style="margin-top:10px"><div class="aw-panel-head"><h2>✦ ANALYST ENGINE</h2></div><div class="aw-panel-body"><div class="engine-card"><div class="brain">◉</div><div><strong id="engine">Analyst ready.</strong><div id="summary" class="aw-muted" style="margin-top:6px">Choose a target or analyze all recorded evidence.</div></div></div></div></section><section class="aw-panel" style="margin-top:10px"><div class="aw-panel-head"><h2>△ PRIORITIES</h2></div><div id="priorities" class="aw-panel-body"><div class="aw-empty">No analysis run yet.</div></div></section></div><section class="aw-panel"><div class="aw-panel-head"><h2>› AI / RULE ANALYSIS</h2><span class="aw-right aw-badge ok">LOCAL</span></div><div class="aw-panel-body"><pre id="analysis" class="aw-pre analysis-box">Choose a target or analyze all recorded evidence.</pre></div></section></div></main></div><div id="toast" class="aw-toast"></div>
<script>
const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));function toast(msg,error=false){const e=$('toast');e.textContent=msg;e.className='aw-toast'+(error?' error':'');e.style.display='block';setTimeout(()=>e.style.display='none',3200)}async function api(path,opt={}){const r=await fetch(path,{headers:{'Content-Type':'application/json'},cache:'no-store',...opt});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||('Request failed: '+r.status));return d}async function boot(){const s=await api('/api/state');for(const d of s.devices||[])$('device').innerHTML+=`<option value="${esc(d.id)}">${esc(d.name)} · ${esc(d.kind)}</option>`;for(const m of(s.ai&&s.ai.models)||[])$('model').innerHTML+=`<option>${esc(m)}</option>`}async function analyze(){$('analysis').textContent='Analyzing local evidence…';$('priorities').innerHTML='<div class="aw-empty">Analyzing…</div>';try{const d=await api('/api/ai-analysis',{method:'POST',body:JSON.stringify({device_id:$('device').value,model:$('model').value})});$('engine').textContent=(d.engine||'AgentWhite analyst')+(d.model?' · '+d.model:'');$('summary').textContent=d.summary||'';$('priorities').innerHTML=(d.priorities||[]).length?(d.priorities||[]).map(p=>`<div class="priority"><b>${esc(p.severity)} · ${esc(p.finding)}</b><br>${esc(p.fix)}</div>`).join(''):'<div class="aw-empty">No priority items produced.</div>';$('analysis').textContent=d.analysis||'Local Ollama is not available; remediation above was generated by the offline rule analyst.';if(d.ai_error)$('analysis').textContent+='\n\nLocal AI error: '+d.ai_error;toast('Analysis complete')}catch(e){$('analysis').textContent=e.message;$('priorities').innerHTML='<div class="aw-empty aw-red">Analysis failed.</div>';toast(e.message,true)}}boot().catch(e=>$('analysis').textContent=e.message)
</script></body></html>'''
AI_HTML = AI_HTML.replace("__AW_COMMON_CSS__", COMMON_CSS).replace("__AW_LOGO__", LOGO_DATA_URI)
